mapper.select:
SELECT puch.create_ymd AS createYmd, pih.weight, IF(pih.neutralize_fl = 0, '미완료', '완료') AS neutralize_fl, IFNULL(fn_codeNm('INTEREST_INFO', pih.interest_info_cd_lst, false),NULL) AS interest_info_cd_lst, IFNULL(fn_codeNm('WATER', pih.water_cd, true), NULL) as water_cd, pih.water_ml, IFNULL(fn_codeNm('ALLERGY', pih.allergy_cd_lst, false),NULL) AS allergy_cd_lst, CONCAT(pih.pet_activity_hour, '시', pih.pet_activity_minute, '분') AS pet_activity_time, CONCAT(pih.pet_sleep_time_hour, '시', pih.pet_sleep_time_minute, '분') AS pet_sleep_time, pih.pet_pee, pih.pet_dung FROM pet_urine_check_history puch INNER JOIN pet_info_history pih ON puch.pet_history_id = pih.pet_history_id WHERE puch.mb_id = #{mbId} AND puch.pet_id = #{petId}
AND puch.urine_check_history_id <= #{urineCheckHistoryId}
GROUP BY DATE_FORMAT(puch.create_ymd, '%Y-%m-%d') limit 5;

SELECT puch.create_ymd, IF(puch.sg_result_score = 6, '음성', '양성') AS sg_result, IF(puch.blood_result_score = 6, '음성', '양성') AS blood_result, IF(puch.bilirubin_result_score = 6, '음성', '양성') AS bilirubin_result, IF(puch.urobilinogen_result_score = 6, '음성', '양성') AS urobilinogen_result, IF(puch.ketone_result_score = 6, '음성', '양성') AS ketone_result, IF(puch.nitrite_result_score = 6, '음성', '양성') AS nitrite_result, IF(puch.glucose_result_score = 6, '음성', '양성') AS glucose_result, IF(puch.leukocyte_result_score = 6, '음성', '양성') AS leukocyte_result, IF(puch.ph_result_score = 6, '음성', '양성') AS ph_result, IF(puch.protein_result_score = 6, '음성', '양성') AS protein_result, IF(puch.ascorbic_acid_result_score = 6, '음성', '양성') AS ascorbic_acid_result FROM pet_urine_check_history puch WHERE puch.mb_id = #{mbId} AND puch.pet_id = #{petId}
AND puch.urine_check_history_id <= #{urineCheckHistoryId}
GROUP BY DATE_FORMAT(puch.create_ymd, '%Y-%m-%d') limit 5;

SELECT
    code AS result_code, code_nm, result_point, result_nm
FROM v_top_result
WHERE urine_check_history_id = #{urineCheckHistoryId}
ORDER BY result_nm, result_point;

SELECT SQL_CALC_FOUND_ROWS urine_chung_do_id, device_type, chungdo_code, blood_rgb, blood_result_score, blood_result_nm, bilirubin_rgb, bilirubin_result_score, bilirubin_result_nm, urobilinogen_rgb, urobilinogen_result_score, urobilinogen_result_nm, ketone_rgb, ketone_result_score, ketone_result_nm, protein_rgb, protein_result_score, protein_result_nm, nitrite_rgb, nitrite_result_score, nitrite_result_nm, glucose_rgb, glucose_result_score, glucose_result_nm, ph_rgb, ph_result_score, ph_result_nm, sg_rgb, sg_result_score, sg_result_nm, leukocyte_rgb, leukocyte_result_score, leukocyte_result_nm, ascorbic_acid_rgb, ascorbic_acid_result_score, ascorbic_acid_result_nm, create_ymd FROM pet_urine_check_chung_do WHERE del_fl = 0
AND device_type = #{deviceType}
ORDER BY create_ymd DESC LIMIT #{pageNo}, #{pageSize};
